(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)
 	
Ext_DigitalValue.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
	
FB_DigitalValue_Logic.Inp_AlmSuppress:=			Inp_AlmSuppress;
FB_DigitalValue_Logic.Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc;
FB_DigitalValue_Logic.Cfg_ControlCabinet:=		Cfg_ConnCabinet;
FB_DigitalValue_Logic.Cfg_ControllerTAG:=		Cfg_ControllerName;
FB_DigitalValue_Logic.Inp_ModuleFault:=			Inp_ModuleFault;
FB_DigitalValue_Logic.Cfg_ProcessTAG:=			Cfg_ProcessTAG;

FB_DigitalValue_Logic.Inp_Value1:=				Inp_Value1;
FB_DigitalValue_Logic.Inp_Value1_Suffix:=		Cfg_Value1_Suffix;
FB_DigitalValue_Logic.Inp_Value2:=				Inp_Value2;
FB_DigitalValue_Logic.Inp_Value2_Suffix:=		Cfg_Value2_Suffix;
FB_DigitalValue_Logic.Inp_Value3:=				Inp_Value3;
FB_DigitalValue_Logic.Inp_Value3_Suffix:=		Cfg_Value3_Suffix;
FB_DigitalValue_Logic.Inp_Value4:=				Inp_Value4;
