FB_DigitalValue_Logic.Inp_Value8:=				Inp_Value8;
FB_DigitalValue_Logic.Inp_Value8_Suffix:=		Cfg_Value8_Suffix;
FB_DigitalValue_Logic.Inp_Value9:=				Inp_Value9;
FB_DigitalValue_Logic.Inp_Value9_Suffix:=		Cfg_Value9_Suffix;

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_DigitalValue_Logic(ENS:=TRUE, 
										Ext_DigitalValue:=Ext_DigitalValue, 
										Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	UPDATING OUTPUS
 *************************************************************************)
 
 Sts_Alarm:=		FB_DigitalValue_Logic.Sts_AlarmTriggered;
